const TZ = 'Asia/Seoul';
const data = $input.first().json;

const workflowName = data.workflow?.name || '(알 수 없음)';
const failedNode = data.execution?.lastNodeExecuted || '(알 수 없음)';
const errorMessage = data.execution?.error?.message || '(에러 메시지 없음)';
const executionUrl = data.execution?.url || '';
const mode = data.execution?.mode || '';
const retryOf = data.execution?.retryOf;

const nowKST = new Intl.DateTimeFormat('ko-KR', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date());

const lines = [
  ':rotating_light: *워크플로우 오류 발생*',
  '',
  `*워크플로우:* ${workflowName}`,
  `*실패 노드:* ${failedNode}`,
  `*에러 메시지:* ${errorMessage}`,
  `*실행 모드:* ${mode}${retryOf ? ` (재시도, 원본 실행 ID: ${retryOf})` : ''}`,
  `*발생 시각:* ${nowKST} (KST)`,
];

if (executionUrl) {
  lines.push(`*실행 로그:* ${executionUrl}`);
}

return [{
  json: {
    slackText: lines.join('\n')
  }
}];
